from random import randint, seed
import pandas as pd

# Method
def task_func(goals, penalties, rng_seed=None):
    if rng_seed is not None:
        seed(rng_seed)

    # Predefined penalty cost
    PENALTY_COST = 100

    def is_non_string_iterable(x):
        return hasattr(x, "__iter__") and not isinstance(x, (str, bytes, dict))

    def to_bounds(value):
        if is_non_string_iterable(value):
            return [max(0, int(v)) for v in list(value)]
        return [max(0, int(value))]

    def expand(bounds, n):
        if not bounds:
            return [0] * n
        if len(bounds) >= n:
            return bounds[:n]
        return bounds + [bounds[-1]] * (n - len(bounds))

    goals_bounds = to_bounds(goals)
    penalties_bounds = to_bounds(penalties)

    if is_non_string_iterable(goals) and is_non_string_iterable(penalties):
        n_teams = max(len(goals_bounds), len(penalties_bounds))
    elif is_non_string_iterable(goals):
        n_teams = len(goals_bounds)
    elif is_non_string_iterable(penalties):
        n_teams = len(penalties_bounds)
    else:
        n_teams = max(1, goals_bounds[0], penalties_bounds[0])

    goals_bounds = expand(goals_bounds, n_teams)
    penalties_bounds = expand(penalties_bounds, n_teams)

    teams = []
    match_results = []

    for idx in range(n_teams):
        team_name = f"Team {idx + 1}"
        team_goals = randint(0, goals_bounds[idx])
        team_penalties = randint(0, penalties_bounds[idx])
        fines = team_penalties * PENALTY_COST

        teams.append(team_name)
        match_results.append(
            f"Goals: {team_goals}, Penalties: {team_penalties}, Fines: {fines}"
        )

    return pd.DataFrame({"Team": teams, "Match Result": match_results})
